  'item.dfa7474b-af31-5c93-8031-0bb797360123.explanation': { ar: 'اجمع الحروف في كلمة واحدة: «T-S-C-H-Ü-S-S» تُكوّن كلمة **Tschüss**. الحرف **Ü** اسمه «u-Umlaut»، والكلمة تنتهي بحرف **S** مزدوج.', src: 'heb6b7cf5', status: 'draft' },
  'item.dfa7474b-af31-5c93-8031-0bb797360123.hint': { ar: '7 أحرف.', src: 'ha81f076c', status: 'draft' },
