  'item.23520fbd-d64b-5992-838d-6c6f27c7e999.question': { ar: 'ما اسم هذا الحرف بالألمانية؟', src: 'hcf53a884', status: 'draft' },
  'item.23520fbd-d64b-5992-838d-6c6f27c7e999.explanation': { ar: 'اسم الحرف «J» بالألمانية **Jot**. انتبه: «G» اسمه «ge»، و«J» اسمه **Jot** — ومن السهل الخلط بينهما.', src: 'h130d2e5c', status: 'draft' },
  'item.23520fbd-d64b-5992-838d-6c6f27c7e999.hint': { ar: 'المطلوب اسم الحرف، لا صوته.', src: 'he22b62ba', status: 'draft' },
