  'notice.a1.1-l03.title': { ar: 'er، sie، es — الضمائر الشخصية', src: 'h538e1979', status: 'draft' },
  'notice.a1.1-l03.body': { ar: 'يتبع الضمير أداة التعريف للاسم الذي يحلّ محلّه: **der Bruder** ← **er**، **die Schwester** ← **sie**، **das Kind** ← **es**. ولأكثر من شخص: **wir** (نحن)، **ihr** (أنتم، لعدة أشخاص بلا رسمية) و**sie** (هم). أما **Sie** بحرف كبير فهي صيغة الاحترام «حضرتك» — لشخص واحد أو لعدة أشخاص. وانتبه إلى فعل واحد: **sprechen** يتغيّر فيه الحرف المتحرّك: er **spricht**. يشرح الدرس 7 هذه القاعدة.', src: 'hdf9d6a94', status: 'draft' },
  'pretest.a1.1-l03.prompt': { ar: 'قل جملة واحدة عن شخص من عائلتك.', src: 'h0e0bbc06', status: 'draft' },
  'phonetik.a1.1-l03.focus': { ar: 'الحرف «ü» في «Bruder – Brüder»', src: 'h97ef8536', status: 'draft' },
  'sprechen.a1.1-l03.prompt': { ar: 'اسأل وأجب عن العائلة: هل لديك إخوة؟ ابن؟ ابنة؟', src: 'h0292244e', status: 'draft' },
  'schreiben.a1.1-l03.task': { ar: 'Ana Chakiri عزباء. هي من المغرب وتتكلّم العربية والألمانية. تتعلّم الألمانية في مدرسة اللغات. املأ استمارة دورة اللغة (الاسم الأول، اسم العائلة، الحالة الاجتماعية، اللغات، البلد).', src: 'h02c13945', status: 'draft' },
  'schreiben.a1.1-l03.field.0': { ar: 'الاسم الأول', src: 'h69a0b0c0', status: 'draft' },
  'schreiben.a1.1-l03.field.1': { ar: 'اسم العائلة', src: 'he4c4f386', status: 'draft' },
  'schreiben.a1.1-l03.field.2': { ar: 'الحالة الاجتماعية', src: 'h8aabebd5', status: 'draft' },
  'schreiben.a1.1-l03.field.3': { ar: 'اللغات', src: 'ha2768b78', status: 'draft' },
